    await db.prepare("DELETE FROM employee_photos WHERE employee_id=? AND company_id=?").bind(str(b.id, 100), id).run();
    await companyAudit(db, id, userId, "employee-photo-removed", str(b.id, 100), "");
    return ok({ ok: true });
